			if(c[i][j]=='B')
			{
				val[++cnt]=-INF;
				t[cnt]=mpir(i,j);
			}
	for(int i=1;i<(1<<cnt);i++)
		for(int j=0;j<cnt;j++)
			if((i>>j)&1)
				sum[i]+=val[j+1];
	printf("%d\n",bfs());
	return 0;
}

int bfs()
{
	int res(0);
	q.push(mtpl(sx,sy,0));
	for(int i=1;i<=n;i++)
		for(int j=1;j<=m;j++)
			for(int k=0;k<(1<<cnt);k++)
				f[i][j][k]=-1;
	f[sx][sy][0]=0;
	while(!q.empty())
	{
		int x,y,s;
		tie(x,y,s)=q.front();
		q.pop();
		if(x==sx && y==sy)
			res=max(res,sum[s]-f[x][y][s]);
		for(int i=0;i<4;i++)
		{
			const int xi=x+fx[i][0];
			const int yi=y+fx[i][1];
			if(xi>0&&xi<=n&&yi>0&&yi<=m&&check(c[xi][yi]))
			{
				int si=s;
				for(int j=0;j<cnt;j++)
					if(check(x,y,xi,yi,j+1))
						si^=(1<<j);
				if(f[xi][yi][si]==-1)
				{
					f[xi][yi][si]=f[x][y][s]+1;
					q.push(mtpl(xi,yi,si));
				}
			}
		}
	}
	return res;
}
